import { request, esc, safeURL, parseImport, formatValue } from './api.js';
import { createPreparationWorkspace } from './preparation.js';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const DOMAINS = [
  {id:'supply',label:'供应与履约',description:'需求基线 · 库存覆盖 · 履约异常',icon:'▤',english:'SUPPLY / FULFILLMENT',fallback:'需求代理数据'},
  {id:'procurement',label:'采购与流程',description:'流程吞吐 · 发票匹配 · 付款风险',icon:'⊞',english:'PROCUREMENT / PROCESS',fallback:'采购流程基线'},
  {id:'service',label:'服务与 SLA',description:'处理时长 · 服务尾部 · SLA 边界',icon:'◷',english:'SERVICE / SLA',fallback:'服务时长基线'},
  {id:'energy',label:'能耗与废弃物',description:'碳强度 · 能耗异常 · 回收记录',icon:'↗',english:'ENERGY / WASTE',fallback:'公开能源基线'},
];
const PAGE_NAMES = {prepare:'赛前研判',global:'全球情报',overview:'基线总览',import:'导入与校验',alerts:'预警与证据',sources:'来源资料',consult:'有据问询',actions:'行动记录',domain:'分析域'};
const KINDS = {public_benchmark:'公开历史基准',public_forecast_snapshot:'已保存公开预测快照',public_historical:'公开历史数据',historical_benchmark:'公开历史基线',live_public_snapshot:'公开快照',saved_public_forecast_snapshot:'已保存公开预测快照',operational:'运营记录',public_snapshot:'公开快照',public:'公开资料',demo:'演示数据',user_upload:'用户导入',document:'文档资料',reference:'参考资料'};
const state = { global:{loaded:false,loading:false,collecting:false,loadVersion:0,status:null,sources:[],runs:[],items:[],query:'',sourceFilter:'',categoryFilter:'',nextCursor:null,searchMode:false,error:null,progress:'',snapshot:null,snapshotLabel:'',snapshotResult:null,snapshotReading:false,snapshotReadVersion:0,snapshotImporting:false},dashboard:{domains:[],alerts:[],source_count:0,document_count:0,record_count:0,llm:{configured:false}},sources:[],intelligence:[],actions:[],connected:false,route:'overview',domain:'supply',domainTab:'public',importTab:'records',queryResults:[],answer:null,scenarios:{},revealedOutcomes:{},query:'',queryDomain:'',template:null,refreshing:false,loadVersion:0,routeVersion:0,viewVersion:0,queryVersion:0,dialogVersion:0,templateVersion:0 };
let preparationMounted=false;
const preparation=createPreparationWorkspace({request,esc,safeURL,time:v=>time(v),toast:(m,e)=>toast(m,e),isCurrent:()=>state.route==='prepare',getHost:()=>$('#page-content')});
const domainById = id => DOMAINS.find(d=>d.id===id) || DOMAINS[0];
const operational = id => state.dashboard.domains.find(d=>d.id===id) || {id,record_count:0,metrics:[],findings:[],limitations:[]};
const intelligence = id => operational(id).public_intelligence || state.intelligence.find(d=>d.domain===id || d.id===id);
const allAlerts = () => state.dashboard.alerts || [];
const time = val => { if(!val) return '未提供'; const d=new Date(val); return Number.isNaN(d.getTime())?String(val):d.toLocaleString('zh-CN',{timeZone:'UTC',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})+' UTC'; };
const dateOnly = val => val ? String(val).slice(0,10) : '未提供';
const external = (url,label='原始来源 ↗') => safeURL(url) ? `<a class="external-link" href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>` : '';
const kind = val => KINDS[val] || val || '来源未分类';
const statusBadge = (status) => `<span class="badge ${status==='available'?'positive':status==='unavailable'?'danger':'warning'}">${esc({available:'数据可用',metadata_only:'仅来源信息',unavailable:'数据未取得'}[status]||'状态待确认')}</span>`;
const severityBadge = value => `<span class="badge ${['critical','high'].includes(value)?'danger':['medium','warning'].includes(value)?'warning':''}">${esc({critical:'严重',high:'高',medium:'中',low:'低',info:'信息',warning:'关注'}[value]||value||'待分级')}</span>`;
const alertStatus = v => ({open:'待核查',acknowledged:'已知悉',resolved:'已解决'}[v]||v||'待核查');
function pageHead(kicker,title,description,actions='') {return `<div class="page-head"><div><span class="eyebrow">${esc(kicker)}</span><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;}
function metricCards(metrics=[],className='') {return `<div class="metric-grid ${className}">${metrics.map(m=>`<div class="metric ${typeof m.value==='string'&&m.value.length>18?'note-metric':''}"><div class="metric-name">${esc(displayLabel(m.label||m.name||'指标'))}</div><div class="metric-value">${esc(metricDisplay(m).value)}<span class="metric-unit">${esc(metricDisplay(m).unit)}</span></div>${m.period?`<p class="field-help">${esc(m.period)}</p>`:''}${m.reason?`<p class="field-help">${esc(m.reason)}</p>`:''}</div>`).join('')}</div>`;}
function empty(title,detail,button='') {return `<div class="empty"><div class="empty-symbol" aria-hidden="true">⊡</div><h3>${esc(title)}</h3><p>${esc(detail)}</p>${button}</div>`;}
function limits(items=[]) {return items.length?`<ul class="plain-list">${items.map(x=>`<li>${esc(typeof x==='object'?formatValue(x):x)}</li>`).join('')}</ul>`:'';}
function toast(message,error=false){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;$('#toast-region').append(el);setTimeout(()=>el.remove(),6500);}
function busy(button,work){if(button.disabled)return Promise.resolve();const old=button.innerHTML;button.disabled=true;button.textContent='处理中…';return work().catch(err=>toast(err.message,true)).finally(()=>{if(button.isConnected){button.disabled=false;button.innerHTML=old;}});}
async function loadData({silent=false}={}) {
  state.refreshing=true;const version=++state.loadVersion,viewVersion=state.viewVersion;
  try {
    const [dash,sources,intel,actions]=await Promise.all([request('/api/dashboard'),request('/api/sources'),request('/api/intelligence'),request('/api/actions')]);
    if(version!==state.loadVersion)return;
    state.dashboard=dash;state.sources=sources.sources||[];state.intelligence=intel.domains||[];state.actions=actions.actions||[];state.connected=true;
    $('#connection-notice').hidden=true;$('#side-status').textContent='私人站点服务已连接';$('#side-status-dot').classList.add('connected');
    $('#llm-top-status').textContent=dash.llm?.configured?`LLM 已配置 · ${dash.llm.model||'外部模型'}`:'LLM 未配置 · 证据检索可用';
    $('#alert-nav-count').textContent=allAlerts().filter(a=>a.status!=='resolved').length;
    if(!silent&&viewVersion===state.viewVersion)render();
  }catch(err){if(version!==state.loadVersion)return;state.connected=false;$('#connection-notice').hidden=false;$('#connection-notice').textContent='私人站点服务尚未连接。保留上次取得的结果；未取得的域保持空状态，不会生成业务指标。请保留输入并刷新页面重试；不要重复提交尚未确认保存的内容。'+(err.message?' '+err.message:'');$('#side-status').textContent='私人站点服务未连接';$('#side-status-dot').classList.remove('connected');$('#llm-top-status').textContent='LLM 状态未取得';if(!silent&&viewVersion===state.viewVersion)render();}
  finally{if(version===state.loadVersion)state.refreshing=false;}
}

function availableCount(){return DOMAINS.filter(d=>intelligence(d.id)?.availability?.status==='available').length;}
function domainCard(d,index){const p=intelligence(d.id);const primary=p?.metric||p?.metrics?.[0];const available=p?.availability?.status==='available',mv=metricDisplay(primary||{});return `<button class="domain-card" data-open-domain="${d.id}"><div class="domain-card-top"><span class="domain-index">0${index+1} / ${d.english.split(' / ')[0]}</span><span class="domain-icon" aria-hidden="true">${d.icon}</span></div><h3>${d.label}</h3><p>${d.description}</p><div class="domain-card-bottom"><span class="domain-count">${available&&primary?esc(mv.value)+' <span class="text-muted">'+esc(mv.unit)+'</span>':'待取得数据'}</span><span class="badge ${available?'positive':'warning'}">${available?(d.id==='energy'?'公开快照':'历史基线'):'证据不足'} ↗</span></div><span class="domain-metric-label">${esc(displayLabel(primary?.primary_label||primary?.label||d.fallback))}</span></button>`;}

function alertsTable(alerts,{compact=false}={}){
  if(!alerts.length)return empty('当前没有待核查预警','规则只会依据已取得的记录或公开分析生成预警。证据不足不代表风险为零。','<a class="button small" href="#import">导入运营记录</a>');
  return `<div class="table-wrap"><table><thead><tr><th>需要核查的事项</th><th>分析域</th><th>级别</th>${compact?'':'<th>状态</th>'}<th><span class="screen-reader">查看证据</span></th></tr></thead><tbody>${alerts.map(a=>`<tr><td class="title-cell"><strong>${esc(a.title||a.rule_id||'风险项')}</strong><p>${esc(a.detail||a.description||'')} </p>${a.data_kind?`<span class="badge">${esc(kind(a.data_kind))}</span>`:''}</td><td>${esc(domainById(a.domain).label)}</td><td>${severityBadge(a.severity)}</td>${compact?'':`<td>${esc(alertStatus(a.status))}</td>`}<td><button class="table-button" data-alert-detail="${esc(a.id)}">证据 ↗</button></td></tr>`).join('')}</tbody></table></div>`;
}
function renderOverview(){const open=allAlerts().filter(a=>a.status!=='resolved');return pageHead('OPERATIONS / EVIDENCE BASELINE','运营风险基线','四个分析域，一条证据链。先看公开数据的可复核结果，再接入自己的运营记录。','<a class="button" href="#import"><span class="button-arrow">↥</span>导入数据</a><button class="button primary" data-analyze>重载已保存分析 <span class="button-arrow">↗</span></button>')+`<div class="overview-banner"><div><div class="banner-title"><span class="banner-symbol">i</span>公开数据已分域建立基线</div><p>历史业务样本用于检验分析方法；能源数据是有时间戳的公开快照。它们不能替代你的库存、合同 SLA、能耗或废弃物观测。</p></div><div class="banner-meta">${availableCount()} / 4 个域取得数据<br>运行方式：GPT-Site 私人站点与持久数据库</div></div><div class="domain-grid">${DOMAINS.map(domainCard).join('')}</div><div class="summary-strip"><div class="summary-item"><div class="summary-value">${esc(state.sources.filter(s=>String(s.kind||'').startsWith('public')).length)}<span>个公开来源</span></div><div class="summary-label">各域样本口径独立披露，不混加</div></div><div class="summary-item"><div class="summary-value">${esc(open.length)}<span>个待核查</span></div><div class="summary-label">基线发现与运营预警</div></div><div class="summary-item"><div class="summary-value">${esc(state.dashboard.record_count||0)}<span>条运营记录</span></div><div class="summary-label">${state.dashboard.demo_loaded?'包含明确标注的演示记录':'从你的文件导入，不自动生成'}</div></div></div><div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>优先核查</h2><p>从事实、分析边界，到下一步行动</p></div><a class="button link-button" href="#alerts">查看全部 ↗</a></div>${alertsTable(open.slice(0,5),{compact:true})}<div class="panel-note">风险项来自明确规则或公开分析。点击证据可核查数据来源、方法与限制。</div></section><div class="stack secondary"><section class="panel"><div class="panel-head"><h2>让判断可追溯</h2><span class="badge">4 步</span></div><div class="panel-body flow">${[['sources','01','核验来源','确认时间范围、样本与许可'],['overview','02','查看分域分析','检查留出集、规则与适用边界'],['consult','03','带着证据问询','先检索，再由已配置模型回答'],['actions','04','留下行动记录','把核查事项交给明确负责人']].map(([route,n,title,detail])=>`<div class="flow-step"><span class="flow-n">${n}</span><a href="#${route}"><h3>${title} ↗</h3><p>${detail}</p></a></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>当前能力</h2></div><div class="panel-body status-list"><div class="status-row"><span>来源与证据检索</span><span class="badge ${state.connected?'positive':'warning'}">${state.connected?'可用':'服务未连接'}</span></div><div class="status-row"><div>LLM 有据答复<p>${state.dashboard.llm?.configured?esc(state.dashboard.llm.model||'已配置模型'):'检索可用；尚未连接外部模型'}</p></div><span class="badge ${state.dashboard.llm?.configured?'positive':'warning'}">${state.dashboard.llm?.configured?'已配置':'未配置'}</span></div><div class="status-row"><span>行动持久化</span><span class="badge">持久 D1</span></div></div></section></div></div>`;}
const LABELS={
 'Positive sales lines':'正向销售明细','Heldout forecast WAPE':'留出期需求预测 WAPE','Heldout demand forecast WAPE':'留出期需求预测 WAPE','Next 14 days forecast sales':'历史情景：后续 14 天销售量','Purchase-item cases':'采购项目案例','Source events':'来源事件','Unambiguous invoice/clear cases':'明确匹配的发票结清案例','Heldout invoice-clear duration MAE':'留出期结清时长 MAE','Heldout invoice-to-clear MAE':'留出期结清时长 MAE','Historical cases':'历史服务案例','Median case duration':'案例时长中位数','Heldout remaining-duration MAE':'留出期剩余时长 MAE','Covered forecast periods':'快照覆盖半小时区间','Best one-hour forecast intensity':'一小时窗口预测碳强度','Best future one-hour forecast intensity':'一小时窗口预测碳强度','Forecast reduction vs earliest start':'较最早可行窗口的预测差值','n':'留出案例数量'};
function displayLabel(label){return LABELS[label]||label;}
function metricDisplay(m){const percent=(m.unit==='ratio'||/WAPE|MAPE|rate/i.test(m.label||m.primary_label||''))&&typeof m.value==='number';return {value:percent?formatValue(m.value*100,1):formatValue(m.value),unit:percent?'%':({hours:'小时',cases:'例',events:'个事件',lines:'条明细',units:'件', 'half-hours':'个区间','gCO2 per 1 kWh scenario':'gCO₂ / 1 kWh 情景'}[m.unit]||m.unit||'')};}
function renderComparison(b){const compare=b.global_median_comparison||b.comparison?.seasonal_naive_7d;if(!compare)return '';const title=b.global_median_comparison?'全局中位数对照':'7 天季节朴素对照';return `<div class="limit-box"><h3>${title}</h3><div class="comparison-values">${Object.entries(compare).filter(([k])=>['mae','wape','n'].includes(k)).map(([k,v])=>`<span>${esc(k.toUpperCase())} <strong>${esc(k==='wape'?formatValue(v*100,1)+'%':formatValue(v))}</strong></span>`).join('')}</div><p class="field-help">与同一留出集比较。误差低一些也不保证实际业务适用。</p></div>`;}
function lineChart(rows,series,title,description){if(!rows.length)return '';const w=650,h=240,left=61,right=17,top=20,bottom=36,innerW=w-left-right,innerH=h-top-bottom;const maximum=Math.max(...rows.flatMap(r=>series.map(v=>Number(r[v.key])||0)),1)*1.06;const x=i=>left+i/(Math.max(rows.length-1,1))*innerW,y=n=>top+(1-(Number(n)||0)/maximum)*innerH;const grid=[0,.25,.5,.75,1].map(v=>`<line x1="${left}" y1="${y(maximum*v)}" x2="${w-right}" y2="${y(maximum*v)}" stroke="#dde3d5" stroke-width="1"/><text x="${left-9}" y="${y(maximum*v)+5}" text-anchor="end" fill="#657159" font-size="14">${esc(new Intl.NumberFormat('zh-CN',{notation:'compact',maximumFractionDigits:1}).format(maximum*v))}</text>`).join('');return `<figure class="data-chart"><figcaption><h3>${esc(title)}</h3><p>${esc(description)}</p><div class="chart-legend">${series.map(v=>`<span><i style="background:${v.color}"></i>${esc(v.label)}</span>`).join('')}</div></figcaption><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(title)}。${esc(description)}"><title>${esc(title)}</title><desc>${esc(description)}；精确值见下方展开表格。</desc>${grid}${series.map(v=>`<polyline fill="none" stroke="${v.color}" stroke-width="2.3" ${v.dash?'stroke-dasharray="6 4"':''} points="${rows.map((r,i)=>`${x(i)},${y(r[v.key])}`).join(' ')}"/>${rows.map((r,i)=>`<circle cx="${x(i)}" cy="${y(r[v.key])}" r="3" fill="${v.color}"><title>${esc(r.date||r.from||i+1)} · ${esc(v.label)}：${esc(formatValue(r[v.key]))}</title></circle>`).join('')}`).join('')}<text x="${left}" y="${h-7}" fill="#657159" font-size="14">${esc(dateOnly(rows[0].date||rows[0].from))}</text><text x="${w-right}" y="${h-7}" text-anchor="end" fill="#657159" font-size="14">${esc(dateOnly(rows.at(-1).date||rows.at(-1).from))}</text></svg><details><summary>查看全部 ${rows.length} 个精确值</summary><div class="table-wrap"><table><thead><tr><th>日期 / 区间</th>${series.map(v=>`<th>${esc(v.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.date||r.from)}</td>${series.map(v=>`<td>${esc(formatValue(r[v.key]))}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details></figure>`;}
function renderHeldoutChart(p){const points=p.baseline?.heldout_predictions;if(!points?.length)return '';return lineChart(points,[{key:'actual_units',label:'留出期实际销售量',color:'#282f23'},{key:'predicted_units',label:'固定起点预测量',color:'#839861',dash:true}],'留出期：预测与实际','历史留出期内的日销售量。全部 '+points.length+' 天均保留，训练期以外的实际值仅用于评估。');}
function renderScenario(p,d){if(!['supply','service','energy'].includes(d.id))return '';const previous=state.scenarios[d.id];let fields='';if(d.id==='supply'){fields=`<div class="field"><label for="scenario-horizon">预测天数</label><input id="scenario-horizon" name="horizon_days" type="number" min="1" max="90" step="1" value="14" required></div><div class="field"><label for="scenario-sku">库存比较 SKU（可选）</label><select id="scenario-sku" name="sku"><option value="">只看聚合需求</option>${Object.keys(p.sku_history||{}).map(k=>`<option value="${esc(k)}">${esc(k)}</option>`).join('')}</select></div><div class="field"><label for="scenario-stock">库存数量（选择 SKU 时填写）</label><input id="scenario-stock" name="inventory_on_hand" type="number" min="0" step="any" placeholder="你提供的库存"></div><div class="field"><label for="scenario-lead">到货提前期 / 天（选择 SKU 时填写）</label><input id="scenario-lead" name="lead_time_days" type="number" min="1" max="90" step="1" placeholder="你提供的提前期"></div>`;}if(d.id==='service'){fields='<div class="field full"><label for="scenario-sla">情景 SLA 阈值 / 小时</label><input id="scenario-sla" name="sla_hours" type="number" min="0.01" step="any" placeholder="例如：24" required><span class="field-help">这是你设定的日历时长情景阈值，不代表源数据的合同 SLA。</span></div>';}if(d.id==='energy'){fields='<div class="field"><label for="scenario-duration">连续运行时长 / 分钟</label><input id="scenario-duration" name="duration_minutes" type="number" min="30" max="1440" step="30" value="60" required></div><div class="field"><label for="scenario-kwh">任务耗电量 / kWh（可选）</label><input id="scenario-kwh" name="task_kwh" type="number" min="0" step="any" placeholder="你提供的实际或计划 kWh"></div><div class="field"><label for="scenario-earliest">最早开始 / ISO 8601（可选）</label><input id="scenario-earliest" name="earliest" placeholder="2026-10-07T16:00:00Z"></div><div class="field"><label for="scenario-latest">完成期限 / ISO 8601（可选）</label><input id="scenario-latest" name="latest" placeholder="2026-10-08T18:00:00Z"></div>';}
 return `<section class="panel"><div class="panel-head"><div><h2>带参数检验情景</h2><p>公开样本上的独立计算，不改写运营数据</p></div><span class="badge">只读情景</span></div><div class="panel-body">${d.id==='supply'?'<div class="notice warning"><strong>SKU 预测置信较弱</strong>参考 SKU 留出 WAPE 约 68–151%。库存差额只是历史场景，不能直接作为补货量；不计算缺少目标服务水平的安全库存。</div>':''}<form id="scenario-form" data-domain="${d.id}"><div class="form-grid">${fields}</div><div class="form-actions"><button class="button primary" type="submit">计算情景 ↗</button></div></form><div id="scenario-output" class="spaced-top">${previous?renderScenarioOutput(previous,d):''}</div></div></section>`;}
function renderScenarioOutput(p,d){const scenario=p.scenario,schedule=p.schedule;let html='<span class="badge warning">情景结果 · 非运营结论</span>';if(scenario){html+=`<p class="scope-line">${esc(scenario.basis||scenario.reason||'')}</p>`;const labels={lead_time_forecast_units:'提前期内预测需求',inventory_on_hand_user_input:'你输入的库存',gap_units:'情景缺口',sla_hours_user_input:'你输入的 SLA 阈值',exceedances:'超过阈值的历史案例',cases:'比较案例数',exceedance_rate:'超过阈值比例'};html+=metricCards(Object.entries(scenario).filter(([k,v])=>k in labels).map(([k,value])=>({label:labels[k],value,unit:k==='exceedance_rate'?'ratio':k==='sla_hours_user_input'?'hours':''})));}if(d.id==='supply'&&p.forecast?.length)html+=lineChart(p.forecast,[{key:'predicted_units',label:'未观测历史情景预测量',color:'#778d55'}],'历史情景：后续需求','此预测发生在历史日志之后，未取得实际结果，未经过留出评分。');if(schedule){if(schedule.status==='unavailable'||schedule.snapshot_stale)html+=`<div class="notice warning spaced-top"><strong>${schedule.snapshot_stale?'快照已过期，需刷新':'窗口不可用'}</strong>${esc(schedule.reason||'保存预测超过一小时。场景结果仅供复核，不应据此直接调度。')}</div>`;if(schedule.best)html+=`<div class="limit-box"><h3>可行窗口中的最低预测碳强度</h3><p>${esc(time(schedule.best.from))} → ${esc(time(schedule.best.to))}</p><div class="spaced-top">${metricCards([{label:'最佳窗口预测碳强度',value:schedule.best.mean_forecast_gco2_per_kwh,unit:'gCO2/kWh'},{label:'相对最早窗口预测差值',value:schedule.estimated_gco2_reduction_per_kwh,unit:'gCO2/kWh'},...(schedule.estimated_task_kgco2!==undefined?[{label:'任务排放情景估计',value:schedule.estimated_task_kgco2,unit:'kgCO2'}]:[])])}</div><p class="scope-line">${esc(schedule.basis||'保存快照上的预测情景，不是已实现的减排量。')}</p></div>`;}return html;}
function renderPublicRecords(p,d){const sample=p.records||[],revealed=state.revealedOutcomes[d.id];return `<section class="panel"><div class="panel-head"><div><h2>可核验样本</h2><p>${d.id==='procurement'||d.id==='service'?'先查看预测时已观测的事件前缀；未来结果单独揭示。':'以下为来源数据样本，完整时间序列仍保留在站点数据快照。'}</p></div><span class="badge">前 6 / ${sample.length}</span></div><div class="panel-body">${sample.length?recordCards(sample.slice(0,6).map(r=>({...r,domain:d.id,source_id:p.provenance?.source_id,occurred_at:r.observed_at||r.date||r.from,payload:r}))):'<p>此来源没有可展示的原始样本。</p>'}${p.outcome_replay?.length?`<div class="form-actions"><button class="button" data-reveal-outcomes="${d.id}">${revealed?'隐藏评估结果':'揭示后续结果，仅供评估'} ↗</button></div><div id="outcome-replay">${revealed?'<div class="notice warning spaced-top"><strong>后续结果只用于回放评估</strong>这些值不是预测时的输入，也不意味着当时已知。</div>'+recordCards(p.outcome_replay.slice(0,6).map(r=>({id:r.evidence_id,domain:d.id,payload:r}))):''}</div>`:''}</div></section>`;}
function bindPublicDomain(){const form=$('#scenario-form');if(form)form.addEventListener('submit',e=>{e.preventDefault();busy(form.querySelector('button[type=submit]'),async()=>{const scenarioDomain=form.dataset.domain,scenarioView=state.viewVersion;const params={};new FormData(form).forEach((value,key)=>{if(String(value).trim())params[key]=['sku','earliest','latest'].includes(key)?String(value).trim():Number(value);});if(scenarioDomain==='supply'&&params.sku&&!('inventory_on_hand'in params&&'lead_time_days'in params))throw new Error('选择 SKU 后请同时填写库存与提前期。');if(scenarioDomain==='supply'&&!params.sku&&('inventory_on_hand'in params||'lead_time_days'in params))throw new Error('库存比较必须选择同一 SKU，不能把混合商品总量当成库存。');const r=await request('/api/intelligence/analyze',{domain:scenarioDomain,params});state.scenarios[scenarioDomain]=r.result;if(scenarioView!==state.viewVersion||state.route!=='domain'||state.domain!==scenarioDomain)return;$('#scenario-output').innerHTML=renderScenarioOutput(r.result,domainById(scenarioDomain));toast('只读情景已计算');});});$$('[data-reveal-outcomes]').forEach(b=>b.addEventListener('click',()=>{state.revealedOutcomes[state.domain]=!state.revealedOutcomes[state.domain];render();}));}
function renderPublic(p,d){if(!p)return `<section class="panel">${empty('尚未取得此域公开分析','取得原始数据后才会显示指标、推荐行动和留出集结果。')}</section>`;
  const avail=p.availability||{},prov=p.provenance||{},b=p.baseline||{},recommend=p.recommendation||{};
  const bMetrics=Object.entries(b.metrics||{}).map(([label,value])=>({label:({mae:'平均绝对误差 MAE',wape:'加权绝对百分比误差 WAPE',rmse:'均方根误差 RMSE',mape:'平均绝对百分比误差 MAPE',median_hours:'中位处理时长',p90_hours:'P90 处理时长'}[label]||label),value,unit:label==='wape'||label==='mape'?'ratio':label==='mae'?(p.metric?.unit==='hours'?'hours':'units'):label==='n'?'cases':''}));
  return `<div class="content-grid"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>公开数据观测</h2><p>${esc(kind(avail.mode))} · ${esc(prov.population||'样本口径见来源')}</p></div>${statusBadge(avail.status)}</div><div class="panel-body">${avail.status==='available'?metricCards(p.metrics||[]):empty(avail.status==='metadata_only'?'当前只有来源信息':'原始数据未取得',avail.reason||'缺少数据时不计算指标。')}${avail.refresh_failed?'<div class="notice warning spaced-top"><strong>最近一次采集失败</strong>仍保留上次有效快照。没有把失败请求当成新的预测。</div>':''}${avail.snapshot_stale?'<div class="notice warning spaced-top"><strong>预测快照已过期</strong>超过一小时的快照需重新取得后才能支持调度决定。此处仅保留分析记录。</div>':''}${avail.reason&&avail.status==='available'?`<p class="scope-line">${esc(avail.reason)}</p>`:''}<div class="scope-line">${esc(prov.period?.from||prov.period?.to?`数据期：${dateOnly(prov.period?.from)} 至 ${dateOnly(prov.period?.to)}`:`观测时间：${time(avail.observed_at)}`)} · ${esc(formatValue(avail.record_count,0))} 条观测</div></div></section><section class="panel"><div class="panel-head"><div><h2>基线与留出检验</h2><p>方法、时间切分与评估口径可检查</p></div><span class="badge ${b.status==='evaluated'?'positive':'warning'}">${b.status==='evaluated'?'已评估':'未评估'}</span></div><div class="panel-body"><p>${esc(b.method||'此域尚未提供可评估的预测基线。')}</p>${b.reason?`<p class="scope-line">${esc(b.reason)}</p>`:''}${b.status==='evaluated'?`<div class="status-list spaced-top"><div class="status-row"><span>训练截止</span><strong>${esc(dateOnly(b.train_end))}</strong></div><div class="status-row"><span>留出期</span><strong>${esc(dateOnly(b.test_start))} → ${esc(dateOnly(b.test_end))}</strong></div></div>${bMetrics.length?`<div class="spaced-top">${metricCards(bMetrics)}</div>`:''}`:''}${renderComparison(b)}${renderHeldoutChart(p)}${b.leakage_controls?.length?`<div class="limit-box"><h3>防止信息泄漏</h3>${limits(b.leakage_controls)}</div>`:''}</div></section>${renderScenario(p,d)}${renderPublicRecords(p,d)}${renderDomainFindings(d.id)}</div><div class="stack"><section class="panel"><div class="panel-head"><h2>下一步核查</h2><span class="badge">建议</span></div><div class="panel-body"><h3>${esc(recommend.title||'核查数据是否适用于当前业务')}</h3><p class="spaced-top">${esc(recommend.detail||'先确认样本时间与业务对象，再决定是否接入运营数据。')}</p><div class="form-actions"><button class="button primary" data-public-action="${d.id}">创建行动记录 ↗</button><button class="button" data-consult-domain="${d.id}">带证据问询</button></div></div></section><section class="panel"><div class="panel-head"><h2>来源链</h2></div><div class="panel-body"><h3>${esc(prov.title||'来源未提供')}</h3><div class="source-tags"><span class="badge">${esc(prov.license||'许可待核实')}</span><span class="badge">${esc(kind(avail.mode))}</span></div><dl class="provenance-list spaced-top"><div><dt>取得时间</dt><dd>${esc(time(prov.retrieved_at||avail.observed_at))}</dd></div><div><dt>样本 / 适用对象</dt><dd>${esc(prov.population||'未提供')}</dd></div><div><dt>记录数量</dt><dd>${esc(formatValue(avail.record_count,0))}</dd></div></dl>${external(prov.url)}${prov.source_id?`<div class="form-actions"><button class="button small" data-source-detail="${esc(prov.source_id)}">核验完整来源</button></div>`:''}${prov.sha256?`<details class="spaced-top"><summary class="field-help">原始文件 SHA-256</summary><p class="mono spaced-top">${esc(prov.sha256)}</p></details>`:''}</div></section><section class="panel"><div class="panel-head"><h2>适用边界</h2><span class="badge warning">必读</span></div><div class="panel-body">${limits(p.limitations||['此基线不能替代当前企业运营记录。'])}</div></section></div></div>`;}
function renderDomainFindings(id){const findings=allAlerts().filter(a=>a.domain===id);return `<section class="panel"><div class="panel-head"><h2>此域发现</h2><span class="badge">${findings.length} 项</span></div>${alertsTable(findings,{compact:true})}</section>`;}
function renderOperational(d){const op=operational(d.id);return `<div class="notice"><strong>你的运营记录，单独计算</strong>公开基线没有你的实时库存、发票、合同 SLA、kWh 或废弃物测量。下面仅显示已导入的运营记录${state.dashboard.demo_loaded?'，演示记录会显式标注':''}。</div><div class="content-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>运营指标</h2><span class="badge">${esc(op.record_count||0)} 条记录</span></div><div class="panel-body">${op.record_count?metricCards(op.metrics||[]):empty('尚未导入运营记录','导入符合此域字段的 CSV 或 JSON 后，即可运行确定性规则。','<a class="button primary" href="#import/'+d.id+'">导入此域数据 ↗</a>')}</div></section>${renderDomainFindings(d.id)}<section class="panel"><div class="panel-head"><h2>记录预览</h2><button class="button small" data-load-records="${d.id}">读取记录</button></div><div id="domain-records">${empty('记录按需读取','最多展示 500 条，便于核查字段与来源。')}</div></section></div><section class="panel"><div class="panel-head"><h2>规则假设与限制</h2></div><div class="panel-body">${limits(op.limitations||[])}<a class="button spaced-top" href="#import/${d.id}">查看导入字段 ↗</a></div></section></div>`;}
function renderDomain(){const d=domainById(state.domain);return pageHead(d.english,d.label,d.description,`<a class="button" href="#overview">← 返回总览</a>${d.id==='energy'?'<button class="button" data-refresh-energy>重新采集 NESO 预测 ↻</button>':''}<a class="button primary" href="#import/${d.id}">接入运营记录 ↥</a>`)+`<div class="tabline" role="group" aria-label="数据类型"><button type="button" aria-pressed="${state.domainTab==='public'}" class="${state.domainTab==='public'?'active':''}" data-domain-tab="public">公开数据基线</button><button type="button" aria-pressed="${state.domainTab==='operational'}" class="${state.domainTab==='operational'?'active':''}" data-domain-tab="operational">我的运营记录 <span class="badge">${operational(d.id).record_count||0}</span></button></div>`+(state.domainTab==='public'?renderPublic(intelligence(d.id),d):renderOperational(d));}
function domainOptions(selected='',all=false){return (all?'<option value="">所有分析域</option>':'')+DOMAINS.map(d=>`<option value="${d.id}" ${selected===d.id?'selected':''}>${d.label}</option>`).join('');}
function renderImport(){return pageHead('INGEST / VALIDATE / TRACE','把数据接入证据链','CSV、JSON 和文字资料分别导入。先检查结构，再把有效记录写入持久数据库。')+`<div class="tabline" role="group" aria-label="导入类型"><button type="button" aria-pressed="${state.importTab==='records'}" class="${state.importTab==='records'?'active':''}" data-import-tab="records">运营记录</button><button type="button" aria-pressed="${state.importTab==='documents'}" class="${state.importTab==='documents'?'active':''}" data-import-tab="documents">知识文档</button></div>`+(state.importTab==='records'?`<div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>01 / 选择文件与分析域</h2><p>支持 UTF-8 CSV 与 JSON，单次最多 1,000 条</p></div><span class="badge">私人站点处理</span></div><div class="panel-body"><form id="import-form"><div class="form-grid"><div class="field"><label for="import-domain">分析域</label><select id="import-domain" name="domain">${domainOptions(state.domain)}</select></div><div class="field"><label for="import-format">文件格式</label><select id="import-format" name="format"><option value="csv">CSV</option><option value="json">JSON</option></select></div><div class="full"><label class="dropzone" id="file-dropzone"><span class="upload-symbol" aria-hidden="true">↥</span><strong>拖入文件，或选择本地文件</strong><small>最多 512 KiB 导入内容 · 暂不支持 XLSX / PDF</small><input type="file" id="import-file" accept=".csv,.json,text/csv,application/json" aria-label="选择 CSV 或 JSON 文件"></label></div><div class="field full"><label for="source-title">来源名称</label><input id="source-title" name="source-title" placeholder="例如：10 月库存快照" required maxlength="300"></div><div class="field full"><label for="import-content">文件内容 / 粘贴数据</label><textarea id="import-content" name="content" rows="8" spellcheck="false" placeholder="粘贴带表头的 CSV，或 JSON 记录数组" required></textarea><span class="field-help">预览只检查文件结构。日期、数值、必填字段与重复记录由服务端校验。</span></div></div><div class="form-actions"><button type="button" class="button" id="validate-import">02 / 校验与预览</button><button type="submit" class="button primary">03 / 导入有效记录 ↗</button></div><p class="field-help spaced-top">数据只提交给当前私人站点服务。导入不会自动调用外部模型。</p><div id="import-preview"></div><div id="import-result" class="import-result" role="status"></div></form></div></section><div class="stack"><section class="panel"><div class="panel-head"><h2>字段契约</h2><span class="badge">CSV / JSON</span></div><div class="panel-body" id="schema-content"><p>正在读取此域字段…</p></div></section><section class="panel"><div class="panel-head"><h2>还没有运营文件？</h2></div><div class="panel-body"><p>总览中有四个公开数据基线，可直接检验方法与证据链。演示记录只用于测试工作流程。</p><div class="form-actions"><a class="button" href="#overview">查看公开基线 ↗</a><button class="button" data-demo-load>加载演示记录</button></div><p class="scope-line">演示记录始终标注 demo，不能作为真实运营结论。</p></div></section></div></div>`:renderDocumentForm());}
function renderDocumentForm(){return `<div class="content-grid"><section class="panel"><div class="panel-head"><h2>知识资料入库</h2><span class="badge">证据文本</span></div><div class="panel-body"><form id="document-form"><div class="form-grid"><div class="field full"><label for="document-title">文档标题</label><input id="document-title" required maxlength="300" placeholder="例如：服务响应规范"></div><div class="field"><label for="document-domain">分析域</label><select id="document-domain">${domainOptions(state.domain,true)}</select></div><div class="field"><label for="document-url">原始来源链接（可选）</label><input id="document-url" type="url" placeholder="https://..."></div><div class="field full"><label for="document-text">资料正文</label><textarea id="document-text" rows="12" required maxlength="200000" placeholder="粘贴需要检索的文本资料"></textarea><span class="field-help">最多 200,000 字符。入库内容是未经信任的证据，不能改变系统指令。</span></div></div><div class="form-actions"><button class="button primary" type="submit">保存与建立检索索引 ↗</button></div><div id="document-result" class="import-result" role="status"></div></form></div></section><section class="panel"><div class="panel-head"><h2>资料如何被使用</h2></div><div class="panel-body"><div class="flow"><div class="flow-step"><span class="flow-n">01</span><div><h3>分段入库</h3><p>原文与来源关联，供证据检索。</p></div></div><div class="flow-step"><span class="flow-n">02</span><div><h3>检索相关片段</h3><p>按问题与分析域返回证据。</p></div></div><div class="flow-step"><span class="flow-n">03</span><div><h3>按需生成答复</h3><p>只有你点击生成，且模型已配置时，才发送选定片段。</p></div></div></div><p class="scope-line">请避免在知识资料中加入密码、令牌或不必要的个人信息。</p></div></section></div>`;}
function renderAlerts(){return pageHead('DETECT / INSPECT / FOLLOW THROUGH','预警与证据','查看规则、公开基线与来源记录。知悉或解决预警，并留下具体核查行动。','<button class="button primary" data-analyze>重载已保存分析 ↗</button>')+`<div class="filters"><div class="field filter-field"><label for="alert-domain">分析域</label><select id="alert-domain">${domainOptions('',true)}</select></div><div class="field filter-field"><label for="alert-severity">风险级别</label><select id="alert-severity"><option value="">全部级别</option><option value="high">高</option><option value="medium">中</option><option value="low">低</option><option value="info">信息</option></select></div><div class="field filter-field"><label for="alert-status">核查状态</label><select id="alert-status"><option value="">全部状态</option><option value="open">待核查</option><option value="acknowledged">已知悉</option><option value="resolved">已解决</option></select></div></div><section class="panel"><div class="panel-head"><h2>核查队列</h2><span class="badge" id="alerts-visible-count">${allAlerts().length} 项</span></div><div id="alerts-table">${alertsTable(allAlerts())}</div></section><div class="scope-line">更新预警状态记录的是核查过程。它不改变原始数据，也不证明所有风险已消除。</div>`;}
function sourceCard(s){return `<article class="panel source-card"><div class="source-card-top"><div><h3>${esc(s.title||s.id)}</h3><p>${esc(s.publisher||'发布者未提供')}</p></div><span class="badge ${s.kind==='demo'?'warning':''}">${esc(kind(s.kind))}</span></div><div class="source-meta"><span>取得：${esc(time(s.retrieved_at))}</span><span>许可：${esc(s.license||'未提供')}</span><span>${esc(s.record_count??0)} 条记录 · ${esc(s.document_count??0)} 个片段</span></div><div class="source-tags">${(s.domain_tags||[]).map(d=>`<span class="badge">${esc(domainById(d).label)}</span>`).join('')}${s.availability?statusBadge(typeof s.availability==='string'?s.availability:s.availability.status):''}</div><div class="source-card-foot"><button class="table-button" data-source-detail="${esc(s.id)}">来源详情 ↗</button>${external(s.url)}</div></article>`;}
function renderSources(){return pageHead('PROVENANCE / SOURCES','来源资料','每个来源保留取得时间、许可、分析域与文件指纹。公开资料、你的文件与演示数据有独立标识。')+`<div class="filters"><div class="field filter-field wide"><label for="source-search">查找来源</label><input type="search" id="source-search" placeholder="标题、发布者或来源 ID"></div><div class="field filter-field"><label for="source-domain">分析域</label><select id="source-domain">${domainOptions('',true)}</select></div><div class="field filter-field"><label for="source-kind">资料类型</label><select id="source-kind"><option value="">全部类型</option><option value="public">公开资料</option><option value="user_upload">用户导入</option><option value="demo">演示数据</option><option value="document">文档资料</option></select></div></div><div class="source-list" id="source-list">${state.sources.length?state.sources.map(sourceCard).join(''):`<section class="panel">${empty('当前没有入库来源','连接服务或导入文件后，来源会在这里列出。')}</section>`}</div>`;}
function renderQueryResults(){return `${state.answer?`<div class="answer-box"><div class="retrieval-meta"><span class="badge positive">LLM 已生成</span><span>${esc(state.answer.model||'已配置模型')}</span></div><h3>有据答复</h3><div class="answer-text">${esc(state.answer.answer||'模型未返回答复。')}</div><div class="answer-citations"><strong>引用证据</strong>${(state.answer.citations||[]).map((c,i)=>`<div><span class="badge">${i+1}</span> ${esc(c.title||c.source_id)} ${external(c.url,'核验来源 ↗')}</div>`).join('')||'<p>模型未返回引用，请勿将此答复视为已核实结论。</p>'}</div><div class="form-actions"><button class="button" data-query-action>保存核查行动 ↗</button></div></div>`:''}${state.queryResults.length?`<div class="split-title"><h2>检索到的证据</h2><span class="badge">${state.queryResults.length} 个片段</span></div>${state.queryResults.map((r,i)=>`<article class="retrieval-card"><div class="retrieval-meta"><span class="badge">证据 ${i+1}</span><span>${esc(kind(r.kind))}</span><span class="mono">${esc(r.chunk_id)}</span></div><h3>${esc(r.title||'证据片段')}</h3><div class="evidence-text">${esc(r.text)}</div><div class="source-card-foot"><button class="table-button" data-source-detail="${esc(r.source_id)}">来源详情 ↗</button>${external(r.url)}</div></article>`).join('')}`:''}`;}
function renderConsult(){const llm=state.dashboard.llm||{};return pageHead('RETRIEVE / REASON / CITE','带着证据问','先检索来源片段。只有模型已配置时，才生成附引用的答复；缺少证据时应保留不确定性。')+`<div class="content-grid"><div><section class="panel"><div class="panel-head"><h2>你的问题</h2><span class="badge ${llm.configured?'positive':'warning'}">${llm.configured?'LLM 已配置':'检索可用 · LLM 未配置'}</span></div><div class="panel-body"><form id="query-form"><div class="field query-box"><label class="screen-reader" for="query-text">输入问题</label><textarea id="query-text" required maxlength="500" placeholder="例如：供应域留出期的预测误差能支持哪些补货判断？">${esc(state.query)}</textarea></div><div class="query-toolbar"><div class="field"><label for="query-domain">检索范围</label><select id="query-domain">${domainOptions(state.queryDomain,true)}</select></div><div class="query-buttons"><button class="button" type="submit" id="search-evidence">检索证据 ↗</button><button class="button primary" type="button" id="generate-answer" ${!llm.configured?'disabled aria-describedby="llm-limit"':''}>生成有据答复 ↗</button></div></div></form></div></section><div class="question-examples" aria-label="问题示例">${['供应域的预测基线有什么限制？','采购流程的异常应先核查什么？','历史服务日志能否证明 SLA 违约？','碳强度如何转换为我的排放量？'].map(q=>`<button data-question="${esc(q)}">${esc(q)}</button>`).join('')}</div><div id="query-results">${renderQueryResults()}</div><div id="query-status" role="status"></div></div><div class="stack"><section class="panel"><div class="panel-head"><h2>答复的依据</h2></div><div class="panel-body"><div class="flow"><div class="flow-step"><span class="flow-n">01</span><div><h3>站点证据检索</h3><p>按相关性返回原文片段，不改写为模型答复。</p></div></div><div class="flow-step"><span class="flow-n">02</span><div><h3>按需调用模型</h3><p>传送本次选定的证据片段，并要求关联引用。</p></div></div><div class="flow-step"><span class="flow-n">03</span><div><h3>回到来源核验</h3><p>答复可能有误。业务决定前核查原文与方法。</p></div></div></div></div></section><div class="notice ${llm.configured?'':'warning'}" id="llm-limit"><strong>${llm.configured?'外部模型已配置':'外部模型尚未配置'}</strong>${llm.configured?`模型：${esc(llm.model||'未提供')}。点击生成会向配置的提供方发送所选证据片段；请先确认资料适合分享。`:'当前可以检索来源和证据。需要由运行服务的人配置环境变量后，才能生成模型答复。浏览器不收集 API 密钥。'}</div></div></div>`;}
function frozenEvidence(snapshot){if(!snapshot||!Object.keys(snapshot).length)return '';return `<details class="limit-box frozen-evidence"><summary>创建时证据快照 · ${esc(time(snapshot.as_of_utc))}</summary><p class="field-help spaced-top">这份摘要与来源指纹随行动保存。重采集或修改行动进展不会将它替换成当前分析。</p><h3 class="spaced-top">${esc(snapshot.title||'关联预警摘要')}</h3><p class="evidence-text spaced-top">${esc(snapshot.detail||'当时没有返回详细摘要。')}</p><div class="retrieval-meta spaced-top"><span class="badge">${esc(kind(snapshot.data_kind))}</span><span class="mono">${esc(snapshot.id||'')}</span></div><div class="field-help">冻结引用：${(snapshot.evidence_ids||[]).map(esc).join('、')||'未提供'}</div>${(snapshot.source_snapshots||[]).map(source=>`<div class="record-card spaced-top"><h3>${esc(source.title||source.id)}</h3><dl class="provenance-list"><div><dt>保存的来源版本</dt><dd class="mono">${esc(source.id||'未提供')}</dd></div><div><dt>当时取得时间</dt><dd>${esc(time(source.retrieved_at))}</dd></div><div><dt>保存的 SHA-256</dt><dd class="mono">${esc(source.sha256||'未提供')}</dd></div></dl><div class="form-actions">${external(source.url,'原始发布入口 ↗')}</div></div>`).join('')}</details>`;}
function actionCard(a){return `<article class="panel action-card"><div class="action-card-head"><h3>${esc(a.title)}</h3><select class="plain-select action-status" data-action-status="${esc(a.id)}" aria-label="行动 ${esc(a.title)} 的状态">${[['open','待开始'],['in_progress','进行中'],['done','已完成']].map(([v,l])=>`<option value="${v}" ${a.status===v?'selected':''}>${l}</option>`).join('')}</select></div>${a.notes?`<p>${esc(a.notes)}</p>`:''}<div class="action-meta"><span>负责人：${esc(a.owner||'未指定')}</span><span>创建：${esc(time(a.created_at))}</span><span>更新：${esc(time(a.updated_at))}</span></div>${frozenEvidence(a.evidence_snapshot)}<div class="action-card-foot"><button class="table-button" data-edit-action="${esc(a.id)}">编辑记录 ↗</button>${a.alert_id?`<button class="table-button" data-alert-detail="${esc(a.alert_id)}">关联预警 ↗</button>`:''}</div></article>`;}
function renderActions(){return pageHead('DECIDE / ASSIGN / RECORD','行动记录','留下核查问题、负责人和进展。记录在私人站点持久保存，可回到关联证据继续验证。','<button class="button primary" data-new-action>创建行动记录 ＋</button>')+`<div class="filters"><div class="field filter-field"><label for="action-filter">进展状态</label><select id="action-filter"><option value="">全部状态</option><option value="open">待开始</option><option value="in_progress">进行中</option><option value="done">已完成</option></select></div><div class="field filter-field wide"><label for="action-search">查找行动</label><input id="action-search" type="search" placeholder="事项或负责人"></div></div><div class="action-list" id="action-list">${state.actions.length?state.actions.map(actionCard).join(''):`<section class="panel">${empty('让发现走向下一步','从预警、公开基线或问询结果创建核查事项，也可以自行记录。','<button class="button primary" data-new-action>创建第一条行动记录 ↗</button>')}</section>`}</div>`;}
function render(){state.viewVersion++;const content=$('#page-content');content.setAttribute('aria-busy','false');$$('#main-nav a').forEach(a=>{const active=a.dataset.route===(state.route==='domain'?'overview':state.route);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#breadcrumb-page').textContent=state.route==='domain'?domainById(state.domain).label:PAGE_NAMES[state.route];if(state.route==='prepare'){content.innerHTML=preparation.render();preparation.bind();if(!preparationMounted){preparationMounted=true;preparation.load();}return;}content.innerHTML=({overview:renderOverview,domain:renderDomain,import:renderImport,alerts:renderAlerts,sources:renderSources,consult:renderConsult,actions:renderActions,global:renderGlobal}[state.route]||renderOverview)();if(state.route==='import'&&state.importTab==='records')loadTemplate(state.domain);bindPage();bindGlobal();if(state.route==='global'&&!state.global.loaded&&!state.global.loading)loadGlobal();}
function route(){if(state.route==='prepare'&&location.hash.slice(1).split('/')[0]!=='prepare'){preparation.dispose();preparationMounted=false;}state.routeVersion++;state.queryVersion++;state.dialogVersion++;if($('#detail-dialog').open)$('#detail-dialog').close();const parts=location.hash.slice(1).split('/');state.route=PAGE_NAMES[parts[0]]?parts[0]:'overview';if(parts[1]&&DOMAINS.some(d=>d.id===parts[1]))state.domain=parts[1];state.domainTab='public';render();window.scrollTo({top:0});}
function showDialog(html){state.dialogVersion++;$('#detail-content').innerHTML=html;const dlg=$('#detail-dialog');if(!dlg.open)dlg.showModal();bindCommon($('#detail-content'));$('#detail-content .dialog-close')?.addEventListener('click',()=>dlg.close());}
const dialogHead=(title,desc='')=>`<div class="dialog-head"><div><h2>${esc(title)}</h2>${desc?`<p>${esc(desc)}</p>`:''}</div><button class="dialog-close" aria-label="关闭详情">×</button></div>`;
async function showSource(id){const source=state.sources.find(s=>s.id===id);if(!source){toast('此来源尚未在来源列表中找到，请刷新资料。',true);return;}showDialog(dialogHead(source.title,'来源 ID：'+source.id)+`<span class="badge">${esc(kind(source.kind))}</span><dl class="provenance-list spaced-top">${[['发布者',source.publisher],['取得时间',time(source.retrieved_at)],['许可',source.license],['可用状态',typeof source.availability==='object'?formatValue(source.availability):source.availability],['记录 / 片段数',`${source.record_count??0} / ${source.document_count??0}`],['SHA-256',source.sha256]].map(([l,v])=>`<div><dt>${esc(l)}</dt><dd class="${l==='SHA-256'?'mono':''}">${esc(v||'未提供')}</dd></div>`).join('')}</dl><div class="form-actions">${external(source.url)}</div><div class="limit-box"><h3>核验提示</h3><p class="field-help">文件指纹用于核对取得的字节。来源公开或历史可用，不代表适合当前业务，也不代表所有字段可以自由转发。</p></div>`);}
function recordCards(records){return `<div class="record-list">${records.map(r=>`<article class="record-card"><h3>${esc(r.id||r.source_id||'来源记录')}</h3><div class="retrieval-meta"><span class="badge">${esc(domainById(r.domain).label)}</span><span>${esc(time(r.occurred_at))}</span>${r.source_id?`<button class="table-button" data-source-detail="${esc(r.source_id)}">来源 ↗</button>`:''}</div><dl class="record-data">${Object.entries(r.payload||r).filter(([k])=>!['id','source_id','domain'].includes(k)).map(([key,value])=>`<div class="record-pair"><dt>${esc(key)}</dt><dd>${esc(formatValue(value))}</dd></div>`).join('')}</dl></article>`).join('')}</div>`;}
async function showAlert(id){const a=allAlerts().find(a=>a.id===id);if(!a){toast('关联预警当前不可用，请刷新后核查。',true);return;}showDialog(dialogHead(a.title,domainById(a.domain).label)+`<div class="retrieval-meta">${severityBadge(a.severity)}<span class="badge">${esc(alertStatus(a.status))}</span>${a.data_kind?`<span class="badge">${esc(kind(a.data_kind))}</span>`:''}<span class="mono">${esc(a.rule_id||a.id)}</span></div><p class="evidence-text">${esc(a.detail||a.description||'未提供详细说明')}</p><div class="dialog-section"><h3>建议核查</h3><p>${esc(a.recommended_action||'核查原始记录与分析条件，再决定后续措施。')}</p></div><div class="dialog-section"><h3>证据引用</h3><div id="alert-evidence" class="record-list"><p class="field-help">正在读取来源和匹配记录…</p></div></div><div class="dialog-section"><div class="field"><label for="alert-update-status">核查状态</label><select id="alert-update-status">${[['open','待核查'],['acknowledged','已知悉'],['resolved','已解决']].map(([v,l])=>`<option value="${v}" ${a.status===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="dialog-actions"><button class="button" id="save-alert-status">保存状态</button><button class="button primary" data-create-alert-action="${esc(a.id)}">创建行动记录 ↗</button></div>`);
  const detailVersion=state.dialogVersion,detailView=state.viewVersion;$('#save-alert-status').addEventListener('click',e=>busy(e.currentTarget,async()=>{await request('/api/alerts/'+encodeURIComponent(a.id),{status:$('#alert-update-status').value},'PATCH');await loadData({silent:true});toast('预警状态已保存');if(detailVersion===state.dialogVersion)$('#detail-dialog').close();if(detailView===state.viewVersion)render();}));
  try{const ids=(a.evidence_ids||[]).slice(0,20);const evidence=await request('/api/evidence?'+ids.map(id=>'id='+encodeURIComponent(id)).join('&'));if(detailVersion!==state.dialogVersion||!$('#detail-dialog').open||!$('#alert-evidence'))return;$('#alert-evidence').innerHTML=(evidence.evidence||[]).map(item=>item.evidence_kind==='source'?`<div class="record-card"><h3>${esc(item.title)}</h3><span class="badge">${esc(kind(item.kind))}</span> <button class="table-button" data-source-detail="${esc(item.id)}">来源详情 ↗</button>${external(item.url)}</div>`:item.evidence_kind==='public_observation'?`<div class="record-card"><div class="retrieval-meta"><span class="badge">公开观测 / 预测时前缀</span><span class="mono">${esc(item.record_id)}</span></div><h3>${esc(item.title)}</h3><p class="evidence-text">${esc(item.text)}</p><div class="form-actions"><button class="table-button" data-source-detail="${esc(item.source_id)}">来源详情 ↗</button></div></div>`:recordCards([item])).join('')+((evidence.missing_ids||[]).length?`<div class="notice warning">尚未找到证据：${evidence.missing_ids.map(esc).join('、')}</div>`:'')+((evidence.evidence||[]).length?'':'<p class="field-help">此项没有返回可核验的证据。请结合此域来源与方法核验。</p>');bindCommon($('#alert-evidence'));}catch(err){if(detailVersion===state.dialogVersion&&$('#detail-dialog').open&&$('#alert-evidence'))$('#alert-evidence').textContent=err.message;}}

function actionDialog(initial={},editing=false){showDialog(dialogHead(editing?'编辑行动记录':'创建行动记录','保存的是核查计划，不会对外发送或执行操作。')+frozenEvidence(initial.evidence_snapshot)+`<form id="action-form"><div class="form-grid"><div class="field full"><label for="action-title">核查事项</label><input id="action-title" required maxlength="300" value="${esc(initial.title||'')}" placeholder="具体要核查什么？"></div><div class="field"><label for="action-owner">负责人（可选）</label><input id="action-owner" maxlength="200" value="${esc(initial.owner||'')}" placeholder="姓名或团队"></div><div class="field"><label for="action-state">状态</label><select id="action-state">${[['open','待开始'],['in_progress','进行中'],['done','已完成']].map(([v,l])=>`<option value="${v}" ${initial.status===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field full"><label for="action-notes">证据、边界与下一步</label><textarea id="action-notes" maxlength="10000" rows="7">${esc(initial.notes||'')}</textarea></div></div><div class="dialog-actions"><button class="button" type="button" id="cancel-action">取消</button><button class="button primary" type="submit">保存行动记录 ↗</button></div></form>`);const actionDialogVersion=state.dialogVersion,actionViewVersion=state.viewVersion;$('#cancel-action').addEventListener('click',()=>$('#detail-dialog').close());$('#action-form').addEventListener('submit',e=>{e.preventDefault();busy($('#action-form button[type=submit]'),async()=>{const data={title:$('#action-title').value.trim(),owner:$('#action-owner').value.trim(),status:$('#action-state').value,notes:$('#action-notes').value.trim()};if(!data.title)throw new Error('请填写核查事项。');if(initial.alert_id)data.alert_id=initial.alert_id;await request('/api/actions'+(editing?'/'+encodeURIComponent(initial.id):''),data,editing?'PATCH':'POST');await loadData({silent:true});if(actionDialogVersion===state.dialogVersion)$('#detail-dialog').close();toast('行动记录已保存');if(state.route==='actions'&&actionViewVersion===state.viewVersion)render();});});}
async function loadTemplate(id){const version=++state.templateVersion,viewVersion=state.viewVersion;try{const t=await request('/api/templates?domain='+encodeURIComponent(id));if(version!==state.templateVersion||viewVersion!==state.viewVersion||state.route!=='import'||state.importTab!=='records'||$('#import-domain')?.value!==id)return;state.template=t;$('#schema-content').innerHTML=`<p>${esc(t.description||'请使用下列字段命名。')}</p><div class="spaced-top"><h3>必填字段</h3><div class="schema-fields">${(t.required_fields||[]).map(f=>`<span class="field-token required">${esc(typeof f==='object'?f.name:f)}</span>`).join('')}</div></div><div class="spaced-top"><h3>可选字段</h3><div class="schema-fields">${(t.optional_fields||[]).map(f=>`<span class="field-token">${esc(typeof f==='object'?f.name:f)}</span>`).join('')}</div></div><div class="form-actions"><button class="button small" id="download-template">下载 CSV 模板 ↧</button></div><p class="scope-line">日期使用 ISO 8601。未带时区的时间按 UTC 解释。不同币种不相加。</p>`;$('#download-template').addEventListener('click',()=>download(t.csv||'',id+'-template.csv','text/csv;charset=utf-8'));}catch(err){if(version===state.templateVersion&&viewVersion===state.viewVersion&&$('#schema-content'))$('#schema-content').textContent=err.message;}}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importPreview(){const content=$('#import-content').value,format=$('#import-format').value;const parsed=parseImport(content,format);if(!parsed.records.length)throw new Error('没有可导入的记录。');if(parsed.records.length>1000)throw new Error('记录超过 1,000 条，请拆分文件。');$('#import-preview').innerHTML=`<div class="import-preview"><div class="preview-heading"><strong>结构预览 · ${parsed.records.length} 条</strong><span>仅显示前 8 条 / ${parsed.headers.length} 个字段</span></div><div class="table-wrap"><table><thead><tr>${parsed.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${parsed.records.slice(0,8).map(r=>`<tr>${parsed.headers.map(h=>`<td>${esc(formatValue(r[h]))}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;return parsed;}
async function readFile(file){if(!file)return;if(file.size>512*1024)throw new Error('文件超过 512 KiB，请拆分后导入。');const ext=file.name.split('.').pop().toLowerCase();if(!['csv','json'].includes(ext))throw new Error('请选择 CSV 或 JSON 文件。');const viewVersion=state.viewVersion,content=await file.text();if(viewVersion!==state.viewVersion||state.route!=='import'||state.importTab!=='records')return;$('#import-format').value=ext;$('#import-content').value=content;if(!$('#source-title').value)$('#source-title').value=file.name;$('#import-preview').innerHTML='';$('#import-result').textContent='已读取文件，尚未提交。';}
function bindCommon(root=document){$$('[data-open-domain]',root).forEach(el=>el.addEventListener('click',()=>{location.hash='domain/'+el.dataset.openDomain;}));$$('[data-alert-detail]',root).forEach(el=>el.addEventListener('click',()=>showAlert(el.dataset.alertDetail)));$$('[data-source-detail]',root).forEach(el=>el.addEventListener('click',()=>showSource(el.dataset.sourceDetail)));$$('[data-new-action]',root).forEach(el=>el.addEventListener('click',()=>actionDialog()));$$('[data-edit-action]',root).forEach(el=>el.addEventListener('click',()=>actionDialog(state.actions.find(a=>a.id===el.dataset.editAction)||{},true)));$$('[data-create-alert-action]',root).forEach(el=>el.addEventListener('click',()=>{const a=allAlerts().find(a=>a.id===el.dataset.createAlertAction);actionDialog({alert_id:a.id,title:a.recommended_action||a.title,notes:`关联预警：${a.title}\n证据：${(a.evidence_ids||[]).join('、')}\n核查边界：${a.detail||''}`});}));}
function bindPage(){bindCommon($('#page-content'));$$('[data-analyze]').forEach(b=>b.addEventListener('click',()=>busy(b,async()=>{await request('/api/analyze',{});await loadData();toast('分析结果已刷新');})));$$('[data-domain-tab]').forEach(b=>b.addEventListener('click',()=>{const selected=b.dataset.domainTab;state.domainTab=selected;render();$('[data-domain-tab="'+selected+'"]')?.focus();}));$$('[data-import-tab]').forEach(b=>b.addEventListener('click',()=>{const selected=b.dataset.importTab;state.importTab=selected;render();$('[data-import-tab="'+selected+'"]')?.focus();}));$$('[data-public-action]').forEach(b=>b.addEventListener('click',()=>{const p=intelligence(b.dataset.publicAction),r=p?.recommendation||{},prov=p?.provenance||{};actionDialog({title:r.title||'核查'+domainById(b.dataset.publicAction).label+'数据适用性',notes:[r.detail||'',`来源：${prov.title||'未提供'} ${prov.url||''}`,`边界：${(p?.limitations||[]).join('；')}`].filter(Boolean).join('\n')});}));$$('[data-consult-domain]').forEach(b=>b.addEventListener('click',()=>{state.queryDomain=b.dataset.consultDomain;state.query=domainById(b.dataset.consultDomain).label+'基线有哪些证据与适用限制？';location.hash='consult';}));$$('[data-load-records]').forEach(b=>b.addEventListener('click',()=>busy(b,async()=>{const recordsView=state.viewVersion;const r=await request('/api/records?domain='+b.dataset.loadRecords);if(recordsView!==state.viewVersion||state.route!=='domain')return;$('#domain-records').innerHTML=r.records?.length?`<div class="panel-body">${recordCards(r.records)}</div>`:empty('尚无运营记录','公开数据的聚合结果在公开基线中单独显示。');bindCommon($('#domain-records'));})));
  $$('[data-refresh-energy]').forEach(b=>b.addEventListener('click',()=>busy(b,async()=>{const refreshView=state.viewVersion;const result=await request('/api/intelligence/refresh',{domain:'energy'});await loadData({silent:true});if(refreshView===state.viewVersion&&state.route==='domain'&&state.domain==='energy')render();if(result.status==='failed'){toast(result.message||'重新采集失败，已保留上次有效快照。',true);}else toast('NESO 预测已重新采集；时间戳与窗口已更新。');})));if(state.route==='domain')bindPublicDomain();if(state.route==='import')bindImport();if(state.route==='alerts')bindAlertFilters();if(state.route==='sources')bindSourceFilters();if(state.route==='consult')bindConsult();if(state.route==='actions')bindActions();}
function bindImport(){if(state.importTab==='documents'){$('#document-form').addEventListener('submit',e=>{e.preventDefault();busy($('#document-form button[type=submit]'),async()=>{const importView=state.viewVersion;const title=$('#document-title').value.trim(),text=$('#document-text').value.trim(),domain=$('#document-domain').value,url=$('#document-url').value.trim();if(!title||!text)throw new Error('请填写标题与资料正文。');const r=await request('/api/documents',{title,text,domain_tags:domain?[domain]:[],url:url||undefined});if(importView===state.viewVersion&&state.route==='import')$('#document-result').innerHTML=`<div class="notice"><strong>资料已入库</strong>${esc(r.chunks)} 个检索片段 · 来源 ${esc(r.source_id)}</div>`;await loadData({silent:true});toast('知识资料已保存');});});return;}
  $('#import-domain').addEventListener('change',e=>{state.domain=e.target.value;state.template=null;$('#schema-content').textContent='正在读取字段…';loadTemplate(state.domain);});$('#validate-import').addEventListener('click',()=>{try{importPreview();toast('文件结构可读取；服务端尚未校验或导入。');}catch(err){toast(err.message,true);}});$('#import-file').addEventListener('change',e=>readFile(e.target.files[0]).catch(err=>toast(err.message,true)));const zone=$('#file-dropzone');zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');readFile(e.dataTransfer.files[0]).catch(err=>toast(err.message,true));});$('#import-content').addEventListener('input',()=>{$('#import-preview').innerHTML='';$('#import-result').textContent='';});$('#import-format').addEventListener('change',()=>{$('#import-preview').innerHTML='';});
  $('#import-form').addEventListener('submit',e=>{e.preventDefault();busy($('#import-form button[type=submit]'),async()=>{const importView=state.viewVersion;importPreview();const r=await request('/api/import',{domain:$('#import-domain').value,format:$('#import-format').value,content:$('#import-content').value,source:{title:$('#source-title').value.trim(),kind:'user_upload'}});if(importView===state.viewVersion&&state.route==='import')$('#import-result').innerHTML=`<div class="notice ${(r.rejected||0)?'warning':''}"><strong>导入完成：${esc(r.imported||0)} 条有效记录</strong>${esc(r.rejected||0)} 条拒绝 · ${esc(r.duplicates_skipped||0)} 条重复跳过${r.errors?.length?`<ul class="import-error-list">${r.errors.slice(0,20).map(x=>`<li>第 ${esc(x.row)} 行：${esc(x.message)}</li>`).join('')}</ul>`:''}<div class="form-actions"><a class="button small" href="#domain/${state.domain}">查看此域结果 ↗</a></div></div>`;await loadData({silent:true});toast('有效记录与来源已保存');});});$$('[data-demo-load]').forEach(b=>b.addEventListener('click',()=>{showDialog(dialogHead('加载演示记录','仅用于验证导入、规则、证据与行动流程。')+'<div class="notice warning"><strong>这些是人工构造的示例，不是真实业务数据</strong>演示来源将标记为 demo，并与公开历史数据分开。加载操作可重复执行，不会重复创建同一批记录。</div><div class="dialog-actions"><button class="button" id="cancel-demo">取消</button><button class="button primary" id="confirm-demo">加载演示记录</button></div>');$('#cancel-demo').addEventListener('click',()=>$('#detail-dialog').close());$('#confirm-demo').addEventListener('click',e=>busy(e.currentTarget,async()=>{const demoDialogVersion=state.dialogVersion,demoView=state.viewVersion;await request('/api/demo/load',{});await loadData({silent:true});if(demoDialogVersion===state.dialogVersion)$('#detail-dialog').close();toast('演示记录已加载并明确标注');if(demoView===state.viewVersion)render();}));}));}
function bindAlertFilters(){const apply=()=>{const domain=$('#alert-domain').value,severity=$('#alert-severity').value,status=$('#alert-status').value;const rows=allAlerts().filter(a=>(!domain||a.domain===domain)&&(!severity||a.severity===severity)&&(!status||a.status===status));$('#alerts-visible-count').textContent=rows.length+' 项';$('#alerts-table').innerHTML=alertsTable(rows);bindCommon($('#alerts-table'));};['#alert-domain','#alert-severity','#alert-status'].forEach(s=>$(s).addEventListener('change',apply));}
function bindSourceFilters(){const apply=()=>{const q=$('#source-search').value.trim().toLowerCase(),domain=$('#source-domain').value,k=$('#source-kind').value;const rows=state.sources.filter(s=>(!q||[s.title,s.publisher,s.id].join(' ').toLowerCase().includes(q))&&(!domain||(s.domain_tags||[]).includes(domain))&&(!k||(k==='public'?String(s.kind||'').startsWith('public')||String(s.kind||'').includes('historical'):s.kind===k)));$('#source-list').innerHTML=rows.length?rows.map(sourceCard).join(''):`<section class="panel">${empty('没有符合条件的来源','修改搜索词或筛选范围。')}</section>`;bindCommon($('#source-list'));};$('#source-search').addEventListener('input',apply);$('#source-domain').addEventListener('change',apply);$('#source-kind').addEventListener('change',apply);}
function bindConsult(){$$('[data-question]').forEach(b=>b.addEventListener('click',()=>{$('#query-text').value=b.dataset.question;state.query=b.dataset.question;$('#query-text').focus();}));$('#query-text').addEventListener('input',e=>{state.query=e.target.value;});$('#query-domain').addEventListener('change',e=>{state.queryDomain=e.target.value;});
 const doQuery=async(llm)=>{const query=$('#query-text').value.trim(),domain=$('#query-domain').value;if(!query)throw new Error('请先输入问题。');if(query.length>500)throw new Error('问题最多 500 字符。');const token=++state.queryVersion,viewVersion=state.viewVersion,routeVersion=state.routeVersion;const current=()=>token===state.queryVersion&&viewVersion===state.viewVersion&&routeVersion===state.routeVersion&&state.route==='consult';state.query=query;state.queryDomain=domain;state.answer=null;state.queryResults=[];$('#query-results').innerHTML='';$('#query-status').textContent=llm?'正在生成附引用答复…':'正在检索站点证据…';const payload={query,domain:domain||undefined,limit:6};
 try{const r=await request(llm?'/api/llm/answer':'/api/rag/search',payload);if(!current())return;if(llm){state.answer=r;state.queryResults=r.citations||[];$('#query-status').textContent='答复已返回。请核查来源与适用边界。';}else{state.queryResults=r.results||[];$('#query-status').textContent=state.queryResults.length?`检索方式：${r.mode||'未提供'} · 这些是原始证据片段。${r.query_expansion==='fixed_bilingual_glossary'?' 使用固定中英词项映射：'+(r.expanded_terms||[]).join('、'):''}`:'没有检索到相关证据。请调整问题、范围，或导入更多资料。';}$('#query-results').innerHTML=renderQueryResults();bindCommon($('#query-results'));bindQueryAction();}
 catch(err){if(!current())return;if(err.status===409){state.queryResults=err.payload?.citations||[];$('#query-results').innerHTML=renderQueryResults();bindCommon($('#query-results'));}$('#query-status').textContent=err.message;throw err;}};
 $('#query-form').addEventListener('submit',e=>{e.preventDefault();return busy($('#search-evidence'),()=>doQuery(false));});$('#generate-answer').addEventListener('click',e=>busy(e.currentTarget,()=>doQuery(true)));bindQueryAction();}

function bindQueryAction(){$$('[data-query-action]').forEach(b=>b.addEventListener('click',()=>actionDialog({title:'核查：'+state.query,notes:`问题：${state.query}\n模型答复（需核验）：${state.answer?.answer||''}\n来源：${(state.answer?.citations||[]).map(c=>c.title+' '+(c.url||c.source_id)).join('\n')}`})));}
function bindActions(){const apply=()=>{const s=$('#action-filter').value,q=$('#action-search').value.toLowerCase().trim();const rows=state.actions.filter(a=>(!s||a.status===s)&&(!q||[a.title,a.owner,a.notes].join(' ').toLowerCase().includes(q)));$('#action-list').innerHTML=rows.length?rows.map(actionCard).join(''):`<section class="panel">${empty('没有匹配的行动记录','修改搜索词，或创建一条新记录。','<button class="button" data-new-action>创建行动记录</button>')}</section>`;bindCommon($('#action-list'));bindActionStatuses();};$('#action-filter').addEventListener('change',apply);$('#action-search').addEventListener('input',apply);bindActionStatuses();}
function bindActionStatuses(){$$('[data-action-status]').forEach(el=>el.addEventListener('change',async()=>{const old=state.actions.find(a=>a.id===el.dataset.actionStatus)?.status;el.disabled=true;try{await request('/api/actions/'+encodeURIComponent(el.dataset.actionStatus),{status:el.value},'PATCH');await loadData({silent:true});toast('行动状态已保存');}catch(err){el.value=old||'open';toast(err.message,true);}finally{el.disabled=false;}}));}
const globalLabel={hazard:'自然灾害',policy:'政策与机构',economy:'经济数据',weather:'天气警报',technology:'科技与航天'};
const globalFresh={uploaded_unverified:'本地上传 · 来源未验证',adapter_refresh_required:'解析器修正后待重采',fresh:'最近取得成功',stale:'取得记录过期',failed:'最近尝试失败',never_collected:'尚未采集',collecting:'正在采集',interrupted:'尝试中断 / 未确认'};
function globalItemCard(i){return `<article class="panel"><div class="panel-head"><div><span class="eyebrow">${esc(globalLabel[i.category]||i.category)} / ${esc(i.source_id)}</span><h2>${esc(i.title)}</h2></div><span class="badge">${i.content_depth==='structured_facts'?'结构化源事实':'标题元数据'}</span></div><div class="panel-body">${i.data_origin==='local_snapshot_upload'?'<div class="notice warning">本地上传快照 · 来源真实性未验证；本站未回连来源。SHA 只检测文件损坏。</div>':''}<dl class="provenance-list"><div><dt>源发布时间</dt><dd>${esc(time(i.published_at))}${i.facts?.time_precision?' · '+esc(i.facts.time_precision):''}</dd></div><div><dt>${i.data_origin==='local_snapshot_upload'?'本地采集器声明首次见到':'本站首次见到'}</dt><dd>${esc(time(i.first_seen_at))}</dd></div><div><dt>${i.data_origin==='local_snapshot_upload'?'本地规则声明时间':'规则记录时间'}</dt><dd>${esc(time(i.alert_created_at))}</dd></div><div><dt>发布者国家 / 语言</dt><dd>${esc(i.source_country||'未知')} / ${esc(i.source_language||'未知')}</dd></div><div><dt>事件国家 / 位置依据</dt><dd>${esc(i.event_country||'未知')} / ${esc(i.location_basis==='source_provided'?'来源提供':'未知')}</dd></div></dl>${(i.rule_alerts||[]).map(a=>`<div class="notice ${a.severity==='high'?'warning':''}">${esc(a.title)}${a.version_id!==i.version_id?' · 旧版本规则记录':''} · ${esc(time(a.alert_created_at))}</div>`).join('')}<div class="form-actions">${external(i.url,'原始条目 ↗')}<button class="button small" data-global-evidence="${esc(i.version_id)}">版本证据与采集回执 ↗</button></div><p class="scope-line mono">${esc(i.version_id)} · ${esc(i.content_hash)}</p></div></article>`}
function renderGlobal(){const g=state.global,s=g.status||{},scheduler=s.scheduler||{},ready=scheduler.enabled&&scheduler.verified;return pageHead('COLLECT / DEDUPE / TRACE','全球情报 · 每日更新','十个精选公开端点。保留来源事实与时间边界，可追溯到每个版本和采集回执。','<button class="button" data-global-reload>重读保存结果 ↻</button><button class="button primary" data-global-collect '+(g.collecting||g.loading||!g.loaded||!g.sources.length?'disabled':'')+'>采集允许的公开来源 ↗</button>')+`<div class="notice ${ready?'':'warning'}"><strong>${ready?'临时日更触发已登记':'日更计划尚未启用'}</strong> · ${esc(scheduler.timezone||'Asia/Kuching')}${scheduler.next_run_at?' · 下一次：'+esc(time(scheduler.next_run_at)):''}<br>${ready?'当前由个人助手的临时任务触发。采集、去重与规则处理来自本产品的确定性脚本；产品独立定时触发尚未接通。':'手动采集接口可用。独立定时触发尚未接通。'}<span class="field-help">来源发布节奏与本站采集节奏分别记录；不保证全球完整覆盖。${!scheduler.last_run_at&&scheduler.status?.includes('first_scheduled_run_pending')?' 首轮计划任务尚未发生；当前数据来自已完成的实际采集。':''}${scheduler.last_run_at?' 最近计划尝试：'+esc(time(scheduler.last_attempt_at||scheduler.last_run_at))+' · '+esc({complete_success:'来源流程全部成功（覆盖仍有边界）',partial_failure:'部分来源失败',failed:'失败',uncertain:'结果未确认'}[scheduler.last_run_status]||'结果未记录'):''}${scheduler.last_complete_success_at?' · 最近完整成功：'+esc(time(scheduler.last_complete_success_at)):''}</span>${ready?`<details><summary>查看日更计划回执</summary><p class="field-help">云端每日任务 · 弹性执行时间 · 下一次运行时间尚未由调度器给出。</p><pre class="record-json">${esc(scheduler.schedule||'未提供')}</pre><span class="field-help mono">${esc(scheduler.automation_id||'')}</span></details>`:''}</div><div id="global-collect-progress" class="notice" role="status" ${g.progress?'':'hidden'}>${esc(g.progress||'')}</div>${g.error?`<div class="notice warning">${esc(g.error)} · 保留此前有效数据。请求结果不明确时先查看采集回执，避免重复提交。</div>`:''}${renderGlobalSnapshotImport()}${metricCards([{label:'登记公开端点',value:s.endpoint_count??g.sources.length,unit:'个'},{label:'发布者家族',value:s.publisher_family_count??'未取得',unit:'个'},{label:'累计保存情报项',value:s.item_count??'未取得',unit:'项'},{label:'规则复核记录',value:s.alert_count??'未取得',unit:'条'}])}<p class="scope-line">本站直接取得 ${esc(s.direct_item_count??s.item_count??'未知')} 项 · 本地上传 ${esc(s.uploaded_item_count??0)} 项；两类来源声明分开保存，相同公开事件可能重复出现。</p><section class="panel"><div class="panel-body"><form id="global-filter-form" class="form-grid"><div class="field"><label for="global-source-filter">来源</label><select id="global-source-filter"><option value="">全部登记来源</option>${g.sources.map(x=>`<option value="${esc(x.id)}" ${g.sourceFilter===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label for="global-category-filter">主题</label><select id="global-category-filter"><option value="">全部主题</option>${Object.entries(globalLabel).map(([id,label])=>`<option value="${id}" ${g.categoryFilter===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="field full"><label for="global-query">检索已保存标题 / 允许元数据</label><input id="global-query" type="search" maxlength="500" value="${esc(g.query)}" placeholder="例如：earthquake、Malaysia、中国、GDACS"></div><div class="form-actions full"><button class="button" type="submit" id="global-apply">词项检索 / 应用筛选 ↗</button><button class="button" type="button" id="global-clear" data-global-clear>清除筛选</button></div></form><p class="scope-line">只检索本站已存词项；不提供语义跨语言匹配。检索词不会发送给外部源。全球元数据检索与现有四域 LLM 问询分开；此处没有生成模型答案。</p></div></section><div class="content-grid"><div class="stack"><div class="section-heading"><h2>${g.searchMode?'词项检索结果':'保存的情报流'}</h2><span>${g.items.length} 项 / ${g.searchMode?'最多20项':'每页50项'}</span></div>${g.items.length?g.items.map(globalItemCard).join(''):`<section class="panel">${empty(g.loading?'正在读取保存结果':'没有匹配的已存情报',g.loaded?'可采集允许源，或更换词项。没有匹配不代表没有事件。':'尚未读取来源与情报记录。')}</section>`}${g.nextCursor&&!g.searchMode?'<button class="button" data-global-next>读取下一页保存结果 ↓</button>':''}</div><div class="stack"><section class="panel"><div class="panel-head"><h2>来源健康与覆盖</h2></div><div class="panel-body">${g.sources.map(x=>`<article class="global-source-summary"><h3>${esc(x.name)}</h3><span class="badge ${x.freshness==='fresh'?'positive':'warning'}">${esc(globalFresh[x.freshness]||x.freshness)}</span><p class="field-help">${x.data_origin==='local_snapshot_upload'?'本地回执声明成功':'本站成功取得'}：${esc(time(x.last_success_at))}<br>最近尝试：${esc(time(x.last_attempt_at))}<br>覆盖：${esc(x.geographic_coverage)}<br>重叠窗口：${esc(x.operational_fetch_plan?.lookback_hours??'滚动快照，历史留存未知')} 小时<br>内容：${x.content_depth==='structured_facts'?'结构化源事实':'标题 / 链接元数据'}</p>${x.coverage?.truncated||x.coverage?.upstream_limit_hit?'<div class="notice warning">条目上限已命中，覆盖不完整。</div>':''}${x.last_attempt?.error?`<p class="field-help">${esc(x.last_attempt.error)}</p>`:''}<details><summary>留存、许可与边界</summary><p>${esc(x.retention)}</p>${limits(x.blindspots)}<p class="field-help">${esc(x.license)}</p>${external(x.license_url,'许可 / 复用说明 ↗')}</details></article>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>最近采集回执</h2><span class="badge">最多25次</span></div><div class="panel-body">${g.runs.map(r=>`<article class="global-source-summary"><h3>${esc(r.source_id)} · ${esc({succeeded:'成功',failed:'失败',running:'进行中'}[r.status]||r.status)}</h3><p class="field-help">${esc(time(r.attempted_at))}<br>新增 ${esc(r.new_items??'未知')} · 更新 ${esc(r.revised_items??'未知')} · 重复 ${esc(r.duplicate_items??'未知')}<br>源 ${esc(r.upstream_count??'未知')} / 保存 ${esc(r.selected_count??'未知')} · ${esc(r.bytes??'未知')} 字节</p>${r.error?`<p>${esc(r.error)}</p>`:''}${r.truncated||r.upstream_limit_hit?'<p class="field-help">有限条目选择，不能视为完整。</p>':''}</article>`).join('')||'<p>尚无采集回执。</p>'}</div></section><section class="panel"><div class="panel-head"><h2>当前采集边界</h2></div><div class="panel-body">${limits(s.coverage_gaps||[])}<p>${esc(s.independent_confirmation_warning||'多个端点可能共享发布者或上游，不能当作独立确认。')}</p><p class="scope-line">上游首次出现时间常常未知。事件时间、发布时间、本站首次见到、摄取、分析和规则记录不是同一个时钟。</p></div></section></div></div>`}
function renderGlobalSnapshotImport(){const g=state.global;return `<section class="panel"><div class="panel-head"><h2>导入本地采集快照</h2><span class="badge">手动交接</span></div><div class="panel-body"><p>本地确定性采集器需要电脑保持唤醒、进程保持运行。关闭后不会执行；下次启动采集当前重叠窗口，并记录漏跑日期，不能补出未知历史。此处手动导入 export-site 生成的 JSON 分片。</p><p class="scope-line">每片最多 1.5 MiB。SHA 仅检测文件完整性；上传来源真实性未验证，本站没有自动同步。原有四域记录与本站直接采集证据独立保存。</p><label for="global-snapshot-file">选择本地快照 JSON</label><input id="global-snapshot-file" type="file" accept=".json,application/json" ${g.snapshotReading||g.snapshotImporting?'disabled':''}><p class="field-help">${esc(g.snapshotLabel||'尚未读取快照；选择文件不会自动提交。')}</p><button class="button" id="global-snapshot-submit" ${!g.snapshot||g.snapshotReading||g.snapshotImporting?'disabled':''}>校验并保存本地快照 ↗</button>${g.snapshotResult?`<div class="notice" role="status">${esc(g.snapshotResult)}</div>`:''}${(g.status?.uploaded_snapshots||[]).length?`<details><summary>查看最近上传完整性回执</summary><pre class="record-json">${esc(JSON.stringify(g.status.uploaded_snapshots,null,2))}</pre></details>`:''}</div></section>`}
async function readGlobalSnapshotFile(file){if(!file)return;const g=state.global,view=state.viewVersion,routeVersion=state.routeVersion,version=++g.snapshotReadVersion;g.snapshot=null;g.snapshotResult=null;g.snapshotReading=true;g.snapshotLabel='正在读取所选快照…';$('#global-snapshot-file').disabled=true;$('#global-snapshot-submit').disabled=true;try{if(file.size>1572864)throw new Error('本地快照超过 1.5 MiB，请用 export-site 的较小 --limit 分片导出。');if(file.name.split('.').pop().toLowerCase()!=='json')throw new Error('请选择本地 export-site 生成的 JSON 文件。');const raw=await file.text();if(version!==g.snapshotReadVersion||view!==state.viewVersion||routeVersion!==state.routeVersion||state.route!=='global')return;let parsed;try{parsed=JSON.parse(raw)}catch{throw new Error('快照不是有效 JSON。')}if(!parsed||parsed.schema_version!=='dormathon.local-intel.snapshot.v1')throw new Error('文件不是约定的本地采集快照。');g.snapshot=parsed;g.snapshotLabel=file.name+' · '+file.size+' 字节 · 尚未提交';}catch(err){if(version===g.snapshotReadVersion)g.snapshotLabel='没有读取有效快照：'+err.message;throw err;}finally{if(version===g.snapshotReadVersion){g.snapshotReading=false;if(view===state.viewVersion&&routeVersion===state.routeVersion&&state.route==='global'){render();$(g.snapshot?'#global-snapshot-submit':'#global-snapshot-file')?.focus({preventScroll:true})}}}}
async function importGlobalSnapshot(){const g=state.global;if(!g.snapshot||g.snapshotImporting)return;const submitted=g.snapshot,routeVersion=state.routeVersion;g.snapshotImporting=true;try{const receipt=await request('/api/global/import-snapshot',{snapshot:submitted});g.snapshotResult=(receipt.status==='already_imported'?'该文件已保存；没有重复写入。':'已校验并保存。')+' 分片声明 '+receipt.items+' 项 / '+receipt.versions+' 版本。来源真实性未验证，自动同步未启用。';if(g.snapshot===submitted){g.snapshot=null;g.snapshotLabel='已提交快照；可选择下一片。'}await loadGlobal({focusSelector:'#global-snapshot-file'});}catch(err){g.snapshotResult='没有确认保存：'+err.message+'。请保留文件；重读回执后可重复提交同一文件。';throw err;}finally{g.snapshotImporting=false;if(state.route==='global'&&state.routeVersion===routeVersion){render();$('#global-snapshot-file')?.focus({preventScroll:true})}}}
function globalFilterBusy(disabled){if(state.route!=='global')return;for(const id of ['global-source-filter','global-category-filter','global-query','global-apply','global-clear']){const node=$('#'+id);if(node)node.disabled=disabled}}
async function loadGlobal({append=false,focusSelector=null}={}){const g=state.global,version=++g.loadVersion,routeVersion=state.routeVersion;g.loading=true;globalFilterBusy(true);try{const args=new URLSearchParams({limit:'50'});if(g.sourceFilter)args.set('source_id',g.sourceFilter);if(g.categoryFilter)args.set('category',g.categoryFilter);if(append&&g.nextCursor)args.set('cursor',g.nextCursor);const [status,sources,runs,items]=await Promise.all([request('/api/global/status'),request('/api/global/sources'),request('/api/global/runs'),g.query.trim()?request('/api/global/search',{query:g.query.trim(),limit:20,source_id:g.sourceFilter,category:g.categoryFilter}):request('/api/global/items?'+args)]);if(version!==g.loadVersion)return;g.status=status;g.sources=sources.sources||[];g.runs=runs.runs||[];g.searchMode=!!g.query.trim();const results=g.searchMode?(items.results||[]).map(r=>({...r.metadata,...r,rule_alerts:[]})):items.items||[];g.items=append?g.items.concat(results):results;g.nextCursor=g.searchMode?null:items.next_cursor;g.loaded=true;g.error=null}catch(err){if(version!==g.loadVersion)return;g.error=err.message;g.loaded=true}finally{if(version===g.loadVersion){g.loading=false;if(state.route==='global'&&routeVersion===state.routeVersion){render();globalFilterBusy(false);if(focusSelector&&!$('#detail-dialog').open)$(focusSelector)?.focus({preventScroll:true})}}}}
async function collectGlobal(){const g=state.global;if(g.collecting)return;g.collecting=true;g.error=null;const targets=g.sources.filter(s=>s.enabled);if(!g.loaded||g.loading||!targets.length){g.collecting=false;throw new Error('来源列表尚未取得，请先读取保存状态。')}try{for(let n=0;n<targets.length;n++){g.progress=`正在采集 ${n+1}/${targets.length}：${targets[n].name}`;if(state.route==='global'){const p=$('#global-collect-progress');p.hidden=false;p.textContent=g.progress}const r=await request('/api/global/collect',{source_id:targets[n].id});if(r.status==='failed')g.progress=`${targets[n].name} 采集失败，已保留上次有效数据。`;}g.progress='本轮有界采集结束，请查看各来源回执；失败与条目截断分别保留。'}catch(err){g.error='采集请求结果未确认：'+err.message;g.progress='已停止提交后续来源；先核对回执。'}finally{g.collecting=false;await loadGlobal()}}
async function showGlobalEvidence(versionId){const view=state.viewVersion;showDialog(dialogHead('情报版本证据','正在读取不可变版本…'));const dialog=state.dialogVersion;try{const e=await request('/api/global/evidence?version_id='+encodeURIComponent(versionId));if(view!==state.viewVersion||dialog!==state.dialogVersion)return;const i=e.metadata,r=e.collection_receipt;$('#detail-content').innerHTML=dialogHead(i.title,'版本 ID：'+e.version_id)+`${e.data_origin==='local_snapshot_upload'?'<div class="notice warning">本地上传快照 · 来源真实性未验证；元数据与响应指纹均为上传者声明。本站没有自动同步或回连来源。</div>':''}<dl class="provenance-list">${[['数据进入方式',e.data_origin==='local_snapshot_upload'?'手动导入本地快照（来源未验证）':'本站直接取得源响应'],['本站导入时间',e.imported_at?time(e.imported_at):'不适用'],['快照载荷完整性指纹（规范化 JSON）',e.snapshot_sha256||'不适用'],['内容指纹',e.content_hash],['采集原始响应 SHA-256',r.raw_sha256||'未知'],['发布者国家 / 语言',(i.source_country||'未知')+' / '+(i.source_language||'未知')],['事件国家 / 位置依据',(i.event_country||'未知')+' / '+i.location_basis],['源事件时间',time(i.event_time)],['源发布时间',time(i.published_at)],['源更新时间',time(i.source_updated_at)],['抓取 / 观察时间',time(e.observed_at)],['摄取时间',time(r.ingested_at)],['分析时间',time(i.analyzed_at)],['解析器',i.parser_version],['许可',i.source_license],['上游首次出现 / 到预警延迟','未知；没有用事件时间替代']].map(([l,v])=>`<div><dt>${esc(l)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><h3>允许保存的源元数据</h3><pre class="record-json">${esc(JSON.stringify(i,null,2))}</pre><h3>采集回执</h3><pre class="record-json">${esc(JSON.stringify(r,null,2))}</pre>${external(i.url,'打开原始条目 ↗')}`;const close=$('#detail-content .dialog-close');close?.addEventListener('click',()=>$('#detail-dialog').close());close?.focus({preventScroll:true})}catch(err){if(view===state.viewVersion&&dialog===state.dialogVersion)$('#detail-content').textContent=err.message}}
function bindGlobal(){if(state.route!=='global')return;$('#global-snapshot-file').addEventListener('change',e=>readGlobalSnapshotFile(e.target.files[0]).catch(err=>toast(err.message,true)));$('#global-snapshot-submit').addEventListener('click',e=>busy(e.currentTarget,importGlobalSnapshot));$$('[data-global-reload]').forEach(b=>b.addEventListener('click',()=>busy(b,()=>loadGlobal())));$$('[data-global-collect]').forEach(b=>b.addEventListener('click',()=>busy(b,collectGlobal)));$$('[data-global-evidence]').forEach(b=>b.addEventListener('click',()=>showGlobalEvidence(b.dataset.globalEvidence)));$$('[data-global-next]').forEach(b=>b.addEventListener('click',()=>busy(b,()=>loadGlobal({append:true}))));$$('[data-global-clear]').forEach(b=>b.addEventListener('click',()=>{state.global.query='';state.global.sourceFilter='';state.global.categoryFilter='';loadGlobal()}));$('#global-filter-form').addEventListener('submit',e=>{e.preventDefault();state.global.sourceFilter=$('#global-source-filter').value;state.global.categoryFilter=$('#global-category-filter').value;state.global.query=$('#global-query').value;loadGlobal({focusSelector:'#global-apply'})})}

function skipToWorkspace(event){event.preventDefault();const main=$('#main');main.focus({preventScroll:true});main.scrollIntoView({block:'start'});}
$('.skip-link').addEventListener('click',skipToWorkspace);$('#refresh-button').addEventListener('click',e=>busy(e.currentTarget,()=>state.route==='prepare'?preparation.load({focusSelector:'[data-prep-refresh]'}):state.route==='global'?loadGlobal():loadData().then(()=>state.connected&&toast('数据已刷新'))));$('#detail-dialog').addEventListener('close',()=>{state.dialogVersion++;});$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});window.addEventListener('hashchange',route);const initial=location.hash.slice(1).split('/');state.route=PAGE_NAMES[initial[0]]?initial[0]:'prepare';if(initial[1]&&DOMAINS.some(d=>d.id===initial[1]))state.domain=initial[1];loadData();
